  3→  AC: @ui-session-stream ac-3 — Auto-scroll behavior with jump-to-bottom button.
  4→-->
  5→<script lang="ts">
  6→	import { type DisplayBlock, shouldAutoScroll as computeShouldAutoScroll, shouldShowJumpButton as computeShowJumpButton } from './session-utils';
  7→	import MessageBlock from './MessageBlock.svelte';
  8→	import ToolCallView from './ToolCallView.svelte';
  9→	import ThinkingBlock from './ThinkingBlock.svelte';
 10→	import SystemBlock from './SystemBlock.svelte';
 11→	import ArrowDown from '@lucide/svelte/icons/arrow-down';
 12→
 13→	let {
 14→		blocks,
 15→		isLive = false,
 16→		streamingText = '',
 17→	}: {
 18→		blocks: DisplayBlock[];
 19→		isLive?: boolean;
 20→		streamingText?: string;
 21→	} = $props();
 22→
 23→	let scrollContainer: HTMLDivElement | undefined = $state();
 24→	let autoScrollActive = $state(true);
 25→	let userScrolling = $state(false);
 26→	let scrollDebounceTimer: ReturnType<typeof setTimeout> | undefined;
 27→
 28→	// AC: @ui-session-stream ac-3 — Pause auto-scroll when user scrolls up
 29→	function handleScroll() {
 30→		if (!scrollContainer) return;
 31→
 32→		const { scrollHeight, scrollTop, clientHeight } = scrollContainer;
 33→
 34→		// Clear existing debounce
 35→		if (scrollDebounceTimer) clearTimeout(scrollDebounceTimer);
 36→		userScrolling = true;
 37→
 38→		scrollDebounceTimer = setTimeout(() => {
 39→			userScrolling = false;
 40→		}, 150);
 41→
 42→		// AC: @ui-session-stream ac-3 — Uses extracted utility for threshold calculation
 43→		autoScrollActive = computeShouldAutoScroll(scrollHeight, scrollTop, clientHeight);
 44→	}
 45→
 46→	// AC: @ui-session-stream ac-3 — Auto-scroll to follow new content
 47→	$effect(() => {
 48→		// Track block count and streaming text to trigger scroll
 49→		const _blockCount = blocks.length;
 50→		const _text = streamingText;
 51→
 52→		if (autoScrollActive && !userScrolling && scrollContainer) {
 53→			requestAnimationFrame(() => {
 54→				if (scrollContainer) {
 55→					scrollContainer.scrollTo({
 56→						top: scrollContainer.scrollHeight,
 57→						behavior: 'auto',
 58→					});
 59→				}
 60→			});
 61→		}
 62→	});
 63→
 64→	function jumpToBottom() {
 65→		autoScrollActive = true;
 66→		if (scrollContainer) {
 67→			scrollContainer.scrollTo({
 68→				top: scrollContainer.scrollHeight,
 69→				behavior: 'smooth',
 70→			});
 71→		}
 72→	}
 73→
 74→	// AC: @ui-session-stream ac-3 — Uses extracted utility for button visibility
 75→	let showJumpButton = $derived(computeShowJumpButton(autoScrollActive, isLive, blocks.length));
 76→</script>
 77→
 78→<div class="relative flex-1 min-h-0">
 79→	<div
 80→		bind:this={scrollContainer}
 81→		class="absolute inset-0 overflow-y-auto px-4 py-2"
 82→		onscroll={handleScroll}
 83→		data-testid="session-stream"
 84→		aria-live={isLive ? 'polite' : undefined}
 85→		aria-label="Session event stream"
 86→		role="log"
 87→	>
 88→		{#each blocks as block (block.seq)}
 89→			{#if block.type === 'message'}
 90→				<MessageBlock {block} />
 91→			{:else if block.type === 'tool_call'}
 92→				<ToolCallView {block} />
 93→			{:else if block.type === 'thinking'}
 94→				<ThinkingBlock {block} />
 95→			{:else if block.type === 'system'}
 96→				<SystemBlock {block} />
 97→			{/if}
 98→		{/each}
 99→
100→		<!-- AC: @ui-session-stream ac-2 — Live streaming text appended to stream -->
101→		{#if isLive && streamingText}
102→			<div class="py-2" data-testid="streaming-text">
103→				<div class="flex items-start gap-3">
104→					<div class="flex-shrink-0 w-7 h-7 rounded-full bg-primary/10 flex items-center justify-center">
105→						<span class="text-xs font-bold text-primary">A</span>
106→					</div>
107→					<div class="flex-1 min-w-0">
108→						<div class="text-sm whitespace-pre-wrap break-words leading-relaxed">
109→							{streamingText}<span class="ds-streaming-cursor">{'\u258A'}</span>
110→						</div>
111→					</div>
112→				</div>
113→			</div>
114→		{/if}
115→
116→		{#if blocks.length === 0 && !streamingText}
117→			<div class="flex items-center justify-center h-full text-muted-foreground/50 text-sm" data-testid="stream-empty">
118→				{#if isLive}
119→					Waiting for agent output...
120→				{:else}
121→					No events recorded for this session.
122→				{/if}
123→			</div>
124→		{/if}
125→	</div>
126→
127→	<!-- AC: @ui-session-stream ac-3 — Jump to bottom button -->
128→	{#if showJumpButton}
129→		<button
130→			class="absolute bottom-4 right-6 flex items-center gap-1.5 px-3 py-1.5 rounded-full bg-primary text-primary-foreground text-xs font-medium shadow-lg hover:bg-primary/90 transition-colors"
131→			onclick={jumpToBottom}
132→			data-testid="jump-to-bottom"
133→		>
134→			<ArrowDown class="size-3.5" />
135→			Jump to bottom
136→		</button>
137→	{/if}
138→</div>
139→
140→<style>
141→	@keyframes cursor-blink {
142→		0%, 100% { opacity: 1; }
143→		50% { opacity: 0; }
144→	}
145→	:global(.ds-streaming-cursor) {
146→		color: var(--design-primary);
147→		animation: cursor-blink 1s step-end infinite;
148→	}
149→	@media (prefers-reduced-motion: reduce) {
